use crate::persistent_vector::PersistentVector;

pub fn build_vector_size(n: i32) -> usize {
    let mut vector = PersistentVector::new();
    let mut i = 0;

    while i < n {
        vector = vector.push_back(i);
        i += 1;
    }

    vector.size()
}

#[cfg(test)]
mod tests {
    use super::build_vector_size;

    #[test]
    fn matches_examples() {
        assert_eq!(build_vector_size(0), 0);
        assert_eq!(build_vector_size(1), 1);
        assert_eq!(build_vector_size(2), 2);
        assert_eq!(build_vector_size(3), 3);
        assert_eq!(build_vector_size(4), 4);
    }

    #[test]
    fn negative_input_produces_empty_vector() {
        assert_eq!(build_vector_size(-3), 0);
    }
}

