use std::env;
use std::io::{self, Write};
use std::process;

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum StoiError {
    InvalidArgument,
    OutOfRange,
}

pub fn parse_n_from_env(default: i32) -> i32 {
    match env::args().nth(1) {
        Some(value) => match parse_i32_prefix(&value) {
            Ok(parsed) => parsed,
            Err(error) => abort_with_stoi_message(error),
        },
        None => default,
    }
}

pub fn parse_i32_prefix(input: &str) -> Result<i32, StoiError> {
    let bytes = input.as_bytes();
    let mut index = 0usize;

    while index < bytes.len() && bytes[index].is_ascii_whitespace() {
        index += 1;
    }

    let mut negative = false;
    if index < bytes.len() {
        match bytes[index] {
            b'+' => index += 1,
            b'-' => {
                negative = true;
                index += 1;
            }
            _ => {}
        }
    }

    let digits_start = index;
    let limit = if negative {
        i32::MAX as u64 + 1
    } else {
        i32::MAX as u64
    };
    let mut magnitude = 0u64;

    while index < bytes.len() {
        let byte = bytes[index];
        if !byte.is_ascii_digit() {
            break;
        }

        magnitude = magnitude
            .checked_mul(10)
            .and_then(|value| value.checked_add((byte - b'0') as u64))
            .ok_or(StoiError::OutOfRange)?;

        if magnitude > limit {
            return Err(StoiError::OutOfRange);
        }

        index += 1;
    }

    if index == digits_start {
        return Err(StoiError::InvalidArgument);
    }

    let signed_value = if negative {
        -(magnitude as i64)
    } else {
        magnitude as i64
    };

    Ok(signed_value as i32)
}

pub fn abort_with_stoi_message(error: StoiError) -> ! {
    let type_name = match error {
        StoiError::InvalidArgument => "std::invalid_argument",
        StoiError::OutOfRange => "std::out_of_range",
    };

    eprintln!("terminate called after throwing an instance of '{type_name}'");
    eprintln!("  what():  stoi");
    let _ = io::stderr().flush();
    process::abort();
}

#[cfg(test)]
mod tests {
    use super::{parse_i32_prefix, StoiError};

    #[test]
    fn parses_plain_number() {
        assert_eq!(parse_i32_prefix("42"), Ok(42));
    }

    #[test]
    fn parses_prefix_like_stoi() {
        assert_eq!(parse_i32_prefix("12abc"), Ok(12));
    }

    #[test]
    fn parses_leading_whitespace_and_sign() {
        assert_eq!(parse_i32_prefix("   -4xyz"), Ok(-4));
    }

    #[test]
    fn rejects_missing_digits() {
        assert_eq!(parse_i32_prefix("+"), Err(StoiError::InvalidArgument));
    }

    #[test]
    fn rejects_out_of_range_values() {
        assert_eq!(parse_i32_prefix("2147483648"), Err(StoiError::OutOfRange));
    }
}

